class solution {
  public:
    Node *addTwoNumbers(Node *head1, Node *head2) {

        if (!head1)
            return head2;
        if (!head2)
            return head1;

        Node *current1 = head1;
        Node *current2 = head2;
        Node *fake = new Node(0);
        Node *fakeCurrent = fake;
        int carry = 0;

        while (current1 != nullptr && current2 != nullptr) {
            int data = carry + current1->data + current2->data;
            carry = 0;

            current1 = current1->next;
            current2 = current2->next;

            if (data >= 10) {
                int digit = data % 10;
                carry = data / 10;

                Node *temp = new Node(digit);
                fakeCurrent->next = temp;
                fakeCurrent = temp;
            } else {
                Node *temp = new Node(data);

                fakeCurrent->next = temp;
                fakeCurrent = temp;
            }
        }

        if (current1 != nullptr) {
            while (current1 != nullptr) {
                int data = current1->data + carry;
                carry = 0;
                if (data >= 10) {
                    int digit = data % 10;
                    carry = data / 10;
                    Node *temp = new Node(digit);
                    fakeCurrent->next = temp;
                    fakeCurrent = temp;
                } else {
                    Node *temp = new Node(data);
                    fakeCurrent->next = temp;
                    fakeCurrent = temp;
                }
                current1 = current1->next;
            }
        }

        if (current2 != nullptr) {
            while (current2 != nullptr) {
                int data = current2->data + carry;
                carry = 0;
                if (data >= 10) {
                    int digit = data % 10;
                    carry = data / 10;
                    Node *temp = new Node(digit);
                    fakeCurrent->next = temp;
                    fakeCurrent = temp;
                } else {
                    Node *temp = new Node(data);
                    fakeCurrent->next = temp;
                    fakeCurrent = temp;
                }
                current2 = current2->next;
            }
        }

        if (current1 == nullptr && current2 == nullptr && carry > 0) {
            Node *temp = new Node(carry);
            fakeCurrent->next = temp;
            fakeCurrent = temp;
        }

        return fake->next;
    }
};

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> mp;

        for (int i = 0; i < nums.size(); i++) {
            int complement = target - nums[i];

            if (mp.find(complement) != mp.end()) {
                return {mp[complement], i};
            }

            mp[nums[i]] = i;
        }

        return {};
    }
};
